use axum::extract::State;
use axum::http::StatusCode;
use axum::Json;
use serde::Deserialize;
use serde_json::{json, Value};

use crate::AppState;

#[derive(Deserialize)]
pub struct CreateBook {
    pub title: String,
}

pub async fn create_book(
    State(state): State<AppState>,
