use axum::body::{to_bytes, Body};
use axum::http::{Request, StatusCode};
use serde_json::Value;
use tower::ServiceExt;

async fn send(app: axum::Router, method: &str, uri: &str, body: Option<&str>) -> (StatusCode, Value) {
    let mut builder = Request::builder().method(method).uri(uri);
    let request = match body {
        Some(b) => builder
            .header("content-type", "application/json")
            .body(Body::from(b.to_string()))
            .unwrap(),
        None => builder.body(Body::empty()).unwrap(),
    };
    let res = app.oneshot(request).await.unwrap();
    let status = res.status();
    let bytes = to_bytes(res.into_body(), usize::MAX).await.unwrap();
    let value = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, value)
}

#[tokio::test]
async fn reviews_resource_works() {
    let app = webapp::build_router();

    let (status, body) = send(app.clone(), "POST", "/reviews",
        Some(r#"{"bookId": 7, "text": "great"}"#)).await;
    assert_eq!(status, StatusCode::CREATED, "POST /reviews: {body}");
    assert_eq!(body["id"], 1);
    assert_eq!(body["bookId"], 7, "book_id must serialize as bookId: {body}");
    assert_eq!(body["text"], "great");

    let (_, b2) = send(app.clone(), "POST", "/reviews",
        Some(r#"{"bookId": 7, "text": "ok"}"#)).await;
    assert_eq!(b2["id"], 2, "ids must auto-increment");
    send(app.clone(), "POST", "/reviews", Some(r#"{"bookId": 99, "text": "other"}"#)).await;

    let (status, list) = send(app.clone(), "GET", "/reviews?bookId=7", None).await;
    assert_eq!(status, StatusCode::OK);
    let texts: Vec<&str> = list.as_array().unwrap().iter()
        .map(|r| r["text"].as_str().unwrap()).collect();
    assert_eq!(texts, vec!["great", "ok"], "reviews for book 7, in order");

    let (_, other) = send(app.clone(), "GET", "/reviews?bookId=99", None).await;
    assert_eq!(other.as_array().unwrap().len(), 1);

    let (status, _) = send(app, "POST", "/books", Some(r#"{"title": "Dune"}"#)).await;
    assert_eq!(status, StatusCode::CREATED, "books route must keep working");
}

