        self.next_id += 1;
        self.books.push(Book { id, title });
        id
    }
}

use serde::Serialize;

#[derive(Clone, Serialize)]
pub struct Review {
    pub id: i64,
    #[serde(rename = "bookId")]
    pub book_id: i64,
    pub text: String,
}

pub struct ReviewRepository {
    reviews: Vec<Review>,
    next_id: i64,
}

impl ReviewRepository {
    pub fn new() -> Self {
        ReviewRepository { reviews: Vec::new(), next_id: 1 }
    }

    pub fn add(&mut self, book_id: i64, text: String) -> Review {
        let review = Review { id: self.next_id, book_id, text };
        self.next_id += 1;
        self.reviews.push(review.clone());
        review
    }

    pub fn list_for_book(&self, book_id: i64) -> Vec<Review> {
        self.reviews.iter().filter(|r| r.book_id == book_id).cloned().collect()
    }
}

